-- --- Valeurs communes par mode ----------------------------------------
-- Table temporaire de la transaction : elle disparait au commit.
create temporary table seed_mode_defaults on commit drop as
select * from jsonb_to_recordset($raccourcia$[{"mode":"image","expected_input":"Image jointe recommandee; texte de contexte optionnel","minimal_context":"Objet, personne, lieu ou scene clairement visible, ou brief textuel assez precis.","sufficient_context":"Image exploitable + objectif compris + aucune contrainte contradictoire.","default_values":"Style photo/visualisation premium; format adapte a l'image source; fond neutre si non precise.","expected_output":"Image finale ou prompt image final si l'interface ne permet pas l'edition directe.","output_format":"Image finale ou prompt image; aucune explication longue sauf blocage.","quality_criteria":"Sujet reconnaissable; rendu propre; consignes respectees; coherence lumiere/matiere; aucun artefact majeur.","preserve_rules":"Identite du sujet, proportions, angle general, lumiere coherente, materiaux plausibles.","avoid_rules":"Deformer le sujet, inventer des elements absurdes, changer l'identite, ajouter du texte illisible.","fallback_if_incomplete":"Si l'image manque, demander une image ou produire un prompt de generation autonome.","admin_notes":"Afficher commande, titre, miniature, description courte, compatibilite et bouton Copier.","qcm_trigger":"Si une variable requise manque et que le contexte ne permet pas de l'inferer avec confiance."},{"mode":"texte","expected_input":"Brief, objectif, audience, ton ou document source selon commande","minimal_context":"Objectif d'ecriture et public cible.","sufficient_context":"Objectif + audience + canal + contraintes de longueur ou ton.","default_values":"Ton clair, direct et professionnel; longueur moyenne; structure scannable.","expected_output":"Texte final pret a publier, envoyer ou integrer.","output_format":"Titre + texte final + variante courte si utile.","quality_criteria":"Clarte; specificite; utilite immediate; ton adapte; zero remplissage; appel a l'action net si pertinent.","preserve_rules":"Intention, niveau de langage, informations fournies, contraintes de marque.","avoid_rules":"Promesses non prouvees, ton generique, survente, invention de chiffres ou de sources.","fallback_if_incomplete":"Si le contexte est incomplet, poser 1 a 3 QCM courts avant de rediger.","admin_notes":"Afficher commande, titre, miniature, description courte, compatibilite et bouton Copier.","qcm_trigger":"Si une variable requise manque et que le contexte ne permet pas de l'inferer avec confiance."},{"mode":"analyse","expected_input":"Document, lien, donnees, brief projet ou texte brut","minimal_context":"Element a analyser et objectif de decision.","sufficient_context":"Source lisible + question d'analyse + criteres de sortie.","default_values":"Analyse factuelle; priorites classees; actions concretes; hypotheses signalees.","expected_output":"Analyse structuree avec constats, priorites et actions.","output_format":"Synthese, tableau des constats, priorites, recommandations.","quality_criteria":"Faits separes des hypotheses; priorisation; angles morts listes; recommandations actionnables.","preserve_rules":"Faits observables, incertitudes, limites de la source, distinction fait/inference.","avoid_rules":"Inventer des donnees, conclure sans preuve, masquer les hypotheses.","fallback_if_incomplete":"Si la source manque, demander le document ou proposer une grille d'analyse a remplir.","admin_notes":"Afficher commande, titre, miniature, description courte, compatibilite et bouton Copier.","qcm_trigger":"Si une variable requise manque et que le contexte ne permet pas de l'inferer avec confiance."}]$raccourcia$::jsonb)
  as d(
    mode text, expected_input text, minimal_context text, sufficient_context text,
    default_values text, expected_output text, output_format text, quality_criteria text,
    preserve_rules text, avoid_rules text, fallback_if_incomplete text,
    admin_notes text, qcm_trigger text
  );

create temporary table seed_qcm_sets on commit drop as
select * from jsonb_to_recordset($raccourcia$[{"key":"qcm-1","qcm":[{"question":"Style final ?","options":["Realiste premium","Editorial","Technique propre","Autre"]},{"question":"Sujet principal ?","options":["Objet visible","Personne visible","Lieu visible","Autre"]},{"question":"Format ?","options":["Meme ratio que l'image","Mobile 9:16","Carre 1:1","Autre"]}],"qcm_block":"1. Style final ? A. Realiste premium B. Editorial C. Technique propre D. Autre\n2. Sujet principal ? A. Objet visible B. Personne visible C. Lieu visible D. Autre\n3. Format ? A. Meme ratio que l'image B. Mobile 9:16 C. Carre 1:1 D. Autre"},{"key":"qcm-2","qcm":[{"question":"Style final ?","options":["Realiste premium","Editorial","Technique propre","Autre"]},{"question":"Format ?","options":["Meme ratio que l'image","Mobile 9:16","Carre 1:1","Autre"]}],"qcm_block":"1. Style final ? A. Realiste premium B. Editorial C. Technique propre D. Autre\n2. Format ? A. Meme ratio que l'image B. Mobile 9:16 C. Carre 1:1 D. Autre"},{"key":"qcm-3","qcm":[{"question":"Audience ?","options":["Client final","Prospect","Equipe interne","Autre"]},{"question":"Ton ?","options":["Clair professionnel","Premium","Direct commercial","Autre"]},{"question":"Longueur ?","options":["Court","Moyen","Detaille","Autre"]}],"qcm_block":"1. Audience ? A. Client final B. Prospect C. Equipe interne D. Autre\n2. Ton ? A. Clair professionnel B. Premium C. Direct commercial D. Autre\n3. Longueur ? A. Court B. Moyen C. Detaille D. Autre"},{"key":"qcm-4","qcm":[{"question":"Objectif ?","options":["Decider","Comprendre","Prioriser","Autre"]},{"question":"Niveau de detail ?","options":["Synthese","Standard","Approfondi","Autre"]},{"question":"Sortie ?","options":["Tableau","Plan d'action","Rapport court","Autre"]}],"qcm_block":"1. Objectif ? A. Decider B. Comprendre C. Prioriser D. Autre\n2. Niveau de detail ? A. Synthese B. Standard C. Approfondi D. Autre\n3. Sortie ? A. Tableau B. Plan d'action C. Rapport court D. Autre"}]$raccourcia$::jsonb)
  as d(key text, qcm jsonb, qcm_block text);

-- --- Raccourcis -------------------------------------------------------
insert into public.prompts (
  external_ref, command, name, slug, mode, category_id, short_description, intention,
  use_cases, tags, expected_input, minimal_context, sufficient_context,
  required_variables, optional_variables, default_values, expected_output, output_format,
  quality_criteria, preserve_rules, avoid_rules, limitations, fallback_if_incomplete,
  input_type, output_type, risk_level, priority, status, show_image_card,
  thumbnail_spec, admin_notes, sort_order, published_at
)
select
  d.external_ref, d.command::extensions.citext, d.name, d.slug, d.mode::public.app_mode, c.id,
  d.short_description, d.intention,
  coalesce(d.use_cases, '{}'), coalesce(d.tags, '{}'),
  coalesce(d.expected_input, m.expected_input),
  coalesce(d.minimal_context, m.minimal_context),
  coalesce(d.sufficient_context, m.sufficient_context),
  coalesce(d.required_variables, '{}'), coalesce(d.optional_variables, '{}'),
  coalesce(d.default_values, m.default_values),
  coalesce(d.expected_output, m.expected_output),
  coalesce(d.output_format, m.output_format),
  coalesce(d.quality_criteria, m.quality_criteria),
  coalesce(d.preserve_rules, m.preserve_rules),
  coalesce(d.avoid_rules, m.avoid_rules),
  d.limitations,
  coalesce(d.fallback_if_incomplete, m.fallback_if_incomplete),
  d.input_type::public.input_type, d.output_type::public.output_type,
  d.risk_level::public.risk_level, d.priority,
  'published'::public.content_status, coalesce(d.show_image_card, false),
  d.thumbnail_spec, coalesce(d.admin_notes, m.admin_notes), d.sort_order, now()
from jsonb_to_recordset($raccourcia$[{"external_ref":"RCI-IMG-001","command":"/xray","name":"Vue X-ray","slug":"xray","mode":"image","category_slug":"image-visualisation-produit","short_description":"Transforme un objet en vue transparente montrant ses composants internes.","intention":"Rendre visible la structure interne plausible d'un objet.","use_cases":["/xray sur une photo produit pour obtenir vue x-ray sans changer l'identite visuelle."],"tags":["xray","technique","produit"],"required_variables":["sujet"],"optional_variables":["style","format","niveau_de_realisme","couleurs","arriere_plan"],"limitations":"Les IA peuvent mal preserver les visages, logos, textes fins et details techniques microscopiques.","input_type":"image","output_type":"image","risk_level":"moyen","priority":"P0","show_image_card":true,"thumbnail_spec":"Miniature avant/apres montrant vue x-ray sur fond propre.","sort_order":1},{"external_ref":"RCI-IMG-002","command":"/explodeview","name":"Vue eclatee","slug":"explodeview","mode":"image","category_slug":"image-visualisation-produit","short_description":"Separe les composants principaux pour expliquer la construction d'un objet.","intention":"Decomposer un objet en pieces logiques tout en gardant l'ordre d'assemblage.","use_cases":["/explodeview sur une photo produit pour obtenir vue eclatee sans changer l'identite visuelle."],"tags":["exploded","produit","3d"],"required_variables":["sujet"],"optional_variables":["style","format","niveau_de_realisme","couleurs","arriere_plan"],"limitations":"Les IA peuvent mal preserver les visages, logos, textes fins et details techniques microscopiques.","input_type":"image","output_type":"image","risk_level":"moyen","priority":"P0","show_image_card":true,"thumbnail_spec":"Miniature avant/apres montrant vue eclatee sur fond propre.","sort_order":2},{"external_ref":"RCI-IMG-003","command":"/crosssection","name":"Coupe transversale","slug":"crosssection","mode":"image","category_slug":"image-visualisation-produit","short_description":"Cree une coupe transversale pedagogique avec couches et details visibles.","intention":"Montrer l'interieur d'un objet ou d'un espace par une coupe nette.","use_cases":["/crosssection sur une photo produit pour obtenir coupe transversale sans changer l'identite visuelle."],"tags":["cutaway","technique","pedagogie"],"required_variables":["sujet","axe_de_coupe"],"optional_variables":["style","format","niveau_de_realisme","couleurs","arriere_plan"],"limitations":"Les IA peuvent mal preserver les visages, logos, textes fins et details techniques microscopiques.","input_type":"image","output_type":"image","risk_level":"moyen","priority":"P0","show_image_card":true,"thumbnail_spec":"Miniature avant/apres montrant coupe transversale sur fond propre.","sort_order":3},{"external_ref":"RCI-IMG-004","command":"/blueprint","name":"Plan blueprint","slug":"blueprint","mode":"image","category_slug":"image-visualisation-produit","short_description":"Produit un rendu bleu technique avec contours, cotes visuelles et annotations courtes.","intention":"Transformer un objet ou lieu en plan technique lisible.","use_cases":["/blueprint sur une photo produit pour obtenir plan blueprint sans changer l'identite visuelle."],"tags":["blueprint","technique","schema"],"required_variables":["sujet"],"optional_variables":["style","format","niveau_de_realisme","couleurs","arriere_plan"],"limitations":"Les IA peuvent mal preserver les visages, logos, textes fins et details techniques microscopiques.","input_type":"image","output_type":"image","risk_level":"moyen","priority":"P0","show_image_card":true,"thumbnail_spec":"Miniature avant/apres montrant plan blueprint sur fond propre.","sort_order":4},{"external_ref":"RCI-IMG-005","command":"/ghostview","name":"Ghost view","slug":"ghostview","mode":"image","category_slug":"image-visualisation-produit","short_description":"Cree une vue fantome premium qui montre interieur et silhouette externe.","intention":"Superposer coque ext